from __future__ import annotations

import logging
import os
import pathlib
import re
import shlex
import subprocess
import threading
import time

from taf.ul.ue.sim.env_setup.utils.ssh_utils import get_ssh

TIMEOUT = 180


def execute_shell_command(cmd: str, logger: logging.Logger) -> None:
    logger.debug(f"Executing shell command: {cmd}")

    try:
        p = subprocess.Popen(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, executable="/bin/bash")

        def worker():
            out, err = p.communicate()
            rc = p.returncode
            logger.debug(f"Shell command output=[{out.decode()}], error=[{err.decode()}], rc={rc}")

        thread = threading.Thread(target=worker)
        thread.start()
        thread.join(TIMEOUT)

        if thread.is_alive():
            logger.debug(f"Timeout: Killing shell command: {cmd}")
            p.kill()
    except Exception as exc:
        logger.debug(f"Shell command exception: {exc}")


def execute_sudo_command(cmd: str, logger: logging.Logger) -> None:
    cmd = f"sudo {cmd}"
    execute_shell_command(cmd, logger)


def execute_remote_sudo_command(host: str, cmd: str, logger: logging.Logger) -> None:
    cmd = f"sudo {cmd}"
    logger.debug(f"Executing on remote {host} sudo command: {cmd}")
    with get_ssh(host, "ute", "ute", timeout=30, logger=logger) as ssh_connection:
        try:
            ssh_connection.execute(cmd, timeout=30)
        except Exception as exc:
            logger.warning(f"Cannot execute on {host} command {cmd}: {exc}")


def download_from_remote(host: str, remote_path: str, local_path: str, logger: logging.Logger) -> None:
    logger.debug(f"Downloading from remote {host} path={remote_path} to local path={local_path}")
    with get_ssh(host, "ute", "ute", timeout=30, logger=logger) as ssh_connection:
        try:
            ssh_connection.files.get(remote_path, local_path, timeout=30)
        except Exception as exc:
            logger.warning(f"Cannot download from {host}: file={remote_path} to local path={local_path}: {exc}")


def upload_to_remote(host: str, local_path: str, remote_path: str, logger: logging.Logger) -> None:
    logger.debug(f"Uploading local file {local_path} to remote {host} path={remote_path}")
    with get_ssh(host, "ute", "ute", timeout=30, logger=logger) as ssh_connection:
        try:
            ssh_connection.files.put(local_path, remote_path, timeout=30)
        except Exception as exc:
            logger.warning(f"Cannot upload file {local_path} to remote {host} path={remote_path}: {exc}")


def _get_alias(prefix: str) -> str:
    return prefix + "_" + str(int(time.time()))


def get_netstat(logger: logging.Logger) -> None:
    cmd = "sudo netstat -nlutp"
    execute_sudo_command(cmd, logger)


def get_esim_procs(logger: logging.Logger) -> None:
    cmd = "ps -ef | grep -E 'edaemon|egate' | grep -v grep"
    execute_shell_command(cmd, logger)


def get_tl_label_from_common_agent_log() -> str | None:
    agent_log = pathlib.Path("/home/ute/testline_init_results/agent.log")
    if agent_log.exists():
        with agent_log.open() as ff:
            for line in ff:
                if match := re.search(r"LABEL.*(CLOUD.*)$", line):
                    return match.group(1)
    return None


def get_tree_output() -> str:
    try:
        curdir = os.curdir
        os.chdir("/home/ute/")
        output = subprocess.run(
            shlex.split(
                'tree -I "MN|test_repo|test_repository|testline_configuration|yaft*|rotta*|robotlte|results|LOGS|logs" '
                '--matchdirs -P "*.log" --prune'
            ),
            capture_output=True,
        )
        os.chdir(curdir)
        return output.stdout.decode("utf-8")
    except Exception as err:
        return f"{err}"


def get_env_output() -> str:
    try:
        output = subprocess.run(shlex.split("env"), capture_output=True)
        return output.stdout.decode("utf-8")
    except Exception as err:
        return f"{err}"
